using System; using System.Threading.Tasks; using Microsoft.AspNetCore.Mvc; namespace AiApi.Controllers { [ApiController] [Route("api/v1/[controller]")] public class IntelligenceController : ControllerBase { [HttpPost("process")] public async Task<IActionResult> ProcessRequest([FromBody] AiRequest request) { if (string.IsNullOrEmpty(request.Prompt)) return BadRequest("المدخلات غير صالحة"); try { var result = await GenerateResponseAsync(request.Prompt); return Ok(new { status = "success", data = result }); } catch (Exception ex) { return StatusCode(500, new { error = "خطأ في المعالجة" }); } } private async Task<string> GenerateResponseAsync(string prompt) { await Task.Delay(500); return $"معالجة الذكاء الاصطناعي لـ: {prompt}"; } } public class AiRequest { public string Prompt { get; set; } } }